// Structured data builders — plain functions returning JSON-serializable objects,
// so schema is generated by code (never a plugin) and can't drift or double-encode.

const SITE_URL = 'https://elc.com.sa';

/**
 * @param aggregateRating Only ever pass real numbers from lib/googleReviews.ts's
 *   GoogleReviewsResult — never fabricated. Omit entirely if reviews aren't
 *   configured yet (the build already does this — see src/pages/{en,ar}/index.astro).
 */
export function organizationSchema(
  aggregateRating?: { rating: number; reviewCount: number },
  locale: 'en' | 'ar' = 'en'
) {
  return {
    '@context': 'https://schema.org',
    '@type': 'EducationalOrganization',
    '@id': `${SITE_URL}/#organization`,
    name: locale === 'ar' ? 'معهد صرح المعرفة' : 'ELC',
    alternateName: locale === 'ar' ? 'ELC' : 'معهد صرح المعرفة',
    url: SITE_URL,
    foundingDate: '2010',
    email: 'info@elc.com.sa',
    telephone: '+966591799917',
    contactPoint: [
      { '@type': 'ContactPoint', telephone: '+966591799917', contactType: 'admissions' },
      { '@type': 'ContactPoint', telephone: '+966546656000', contactType: 'WhatsApp' },
      { '@type': 'ContactPoint', telephone: '+966126305553', contactType: 'customer service' },
      { '@type': 'ContactPoint', telephone: '+966126306030', contactType: 'customer service' },
    ],
    address: {
      '@type': 'PostalAddress',
      streetAddress: 'Abdullah Al-Suleiman Street, Al Fayahaa District',
      addressLocality: 'Jeddah',
      addressRegion: 'Makkah Province',
      addressCountry: 'SA',
      postalCode: '23231',
    },
    geo: {
      '@type': 'GeoCoordinates',
      latitude: 21.4971147,
      longitude: 39.2156796,
    },
    sameAs: [
      'https://www.facebook.com/ELCJeddah',
      'https://twitter.com/elcjeddah',
      'https://www.instagram.com/elcjeddah',
      'https://www.snapchat.com/add/elcjeddah',
      'https://www.youtube.com/c/ELCInst',
      'https://www.linkedin.com/company/elcjeddah',
    ],
    ...(aggregateRating && {
      aggregateRating: {
        '@type': 'AggregateRating',
        ratingValue: aggregateRating.rating,
        reviewCount: aggregateRating.reviewCount,
      },
    }),
  };
}

export function localBusinessSchema(
  aggregateRating?: { rating: number; reviewCount: number },
  locale: 'en' | 'ar' = 'en'
) {
  return {
    '@context': 'https://schema.org',
    '@type': 'LocalBusiness',
    '@id': `${SITE_URL}/#localbusiness`,
    name: locale === 'ar' ? 'معهد صرح المعرفة' : 'ELC',
    alternateName: locale === 'ar' ? 'ELC' : 'معهد صرح المعرفة',
    url: SITE_URL,
    email: 'info@elc.com.sa',
    telephone: '+966591799917',
    address: {
      '@type': 'PostalAddress',
      streetAddress: 'Abdullah Al-Suleiman Street, Al Fayahaa District',
      addressLocality: 'Jeddah',
      addressRegion: 'Makkah Province',
      addressCountry: 'SA',
      postalCode: '23231',
    },
    geo: {
      '@type': 'GeoCoordinates',
      latitude: 21.4971147,
      longitude: 39.2156796,
    },
    openingHoursSpecification: [
      {
        '@type': 'OpeningHoursSpecification',
        dayOfWeek: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'],
        opens: '09:00',
        closes: '21:00',
      },
      {
        '@type': 'OpeningHoursSpecification',
        dayOfWeek: 'Saturday',
        opens: '09:00',
        closes: '17:00',
      },
    ],
    priceRange: '$$',
    sameAs: [
      'https://www.facebook.com/ELCJeddah',
      'https://twitter.com/elcjeddah',
      'https://www.instagram.com/elcjeddah',
      'https://www.youtube.com/c/ELCInst',
      'https://www.linkedin.com/company/elcjeddah',
    ],
    ...(aggregateRating && {
      aggregateRating: {
        '@type': 'AggregateRating',
        ratingValue: aggregateRating.rating,
        reviewCount: aggregateRating.reviewCount,
      },
    }),
  };
}

export function faqPageSchema(faqs: { question: string; answer: string }[]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map((faq) => ({
      '@type': 'Question',
      name: faq.question,
      acceptedAnswer: { '@type': 'Answer', text: faq.answer },
    })),
  };
}

export function breadcrumbSchema(items: { name: string; url: string }[]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: item.name,
      item: item.url,
    })),
  };
}

export function courseSchema(course: {
  name: string;
  description: string;
  price?: number;
  currency?: string;
  durationText?: string;
  url: string;
  providerName?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Course',
    name: course.name,
    description: course.description,
    provider: { '@type': 'EducationalOrganization', name: course.providerName ?? 'ELC', sameAs: SITE_URL },
    hasCourseInstance: {
      '@type': 'CourseInstance',
      courseMode: 'Onsite',
      ...(course.durationText ? { duration: course.durationText } : {}),
    },
    ...(course.price !== undefined ? {
      offers: {
        '@type': 'Offer',
        price: course.price,
        priceCurrency: course.currency ?? 'SAR',
        url: course.url,
      },
    } : {}),
  };
}

export function serviceSchema(service: {
  name: string;
  description: string;
  url: string;
  areaServed?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'EducationalService',
    '@id': `${service.url}#service`,
    name: service.name,
    description: service.description,
    provider: { '@type': 'EducationalOrganization', name: 'ELC', sameAs: SITE_URL },
    url: service.url,
    ...(service.areaServed && { areaServed: service.areaServed }),
  };
}

export function articleSchema(article: {
  headline: string;
  description: string;
  datePublished: string;
  dateModified?: string;
  author?: string;
  url: string;
  image?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: article.headline,
    description: article.description,
    datePublished: article.datePublished,
    ...(article.dateModified && { dateModified: article.dateModified }),
    author: { '@type': 'Organization', name: article.author ?? 'ELC' },
    publisher: { '@type': 'Organization', name: 'ELC', url: SITE_URL },
    url: article.url,
    ...(article.image && { image: article.image }),
  };
}

export function eventSchema(event: {
  name: string;
  description: string;
  startDate: string;
  url: string;
  location?: string;
  image?: string;
  organizer?: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Event',
    name: event.name,
    description: event.description,
    startDate: event.startDate,
    url: event.url,
    organizer: { '@type': 'Organization', name: event.organizer ?? 'ELC' },
    ...(event.location && {
      location: {
        '@type': 'Place',
        name: event.location,
        address: {
          '@type': 'PostalAddress',
          streetAddress: 'Abdullah Al-Suleiman Street, Al Fayahaa District',
          addressLocality: 'Jeddah',
          addressCountry: 'SA',
        },
      },
    }),
    ...(event.image && { image: event.image }),
  };
}

export function reviewSchema(review: {
  author: string;
  rating: number;
  text: string;
  datePublished: string;
}) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Review',
    author: { '@type': 'Person', name: review.author },
    reviewRating: { '@type': 'Rating', ratingValue: review.rating, bestRating: 5 },
    reviewBody: review.text,
    datePublished: review.datePublished,
  };
}

export function contactPointSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'ContactPoint',
    contactType: 'Customer Service',
    telephone: '+966591799917',
    email: 'info@elc.com.sa',
    availableLanguage: ['en', 'ar'],
  };
}

export function aboutPageSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'AboutPage',
    name: 'About ELC',
    description: 'Learn about ELC - Saudi Arabia\'s premier English language institute',
    url: `${SITE_URL}/en/about/`,
    publisher: organizationSchema(),
  };
}
